document.getElementById("formulario-imc").addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("peso").value),a=parseFloat(document.getElementById("altura").value)/100;if(isNaN(t)||isNaN(a)||t<=0||a<=0)return void alert("Por favor ingresa valores válidos.");const n=t/(a*a),o=n.toFixed(1);let i="",r="";n<18.5?(i="Bajo peso",r="Es recomendable consultar a un nutricionista para asegurar una alimentación equilibrada."):n<25?(i="Peso normal",r="¡Buen trabajo! Mantén hábitos saludables de alimentación y actividad física."):n<30?(i="Sobrepeso",r="Considera aumentar la actividad física y revisar tu alimentación con un profesional."):(i="Obesidad",r="Es importante buscar orientación médica y nutricional para mejorar tu salud."),document.getElementById("valor").textContent=o,document.getElementById("categoria").textContent=i,document.getElementById("recomendacion").textContent=r;document.getElementById("resultado").classList.remove("oculto")});